    public static class NativeWire
    {
        public static ulong Read(byte[] bytes, int offset, int count)
        {
            if (bytes == null || count < 1 || count > 8 || offset < 0 || offset > bytes.Length - count)
                throw new ArgumentException("Invalid integer range");
            ulong value = 0;
            for (int i = 0; i < count; i++) value |= (ulong)bytes[offset + i] << (8 * i);
            return value;
        }
        public static void Write(byte[] bytes, int offset, int count, ulong value)
        {
            if (bytes == null || count < 1 || count > 8 || offset < 0 || offset > bytes.Length - count)
                throw new ArgumentException("Invalid integer range");
            if (count < 8 && value >> (count * 8) != 0) throw new ArgumentException("Integer overflow");
            for (int i = 0; i < count; i++) bytes[offset + i] = (byte)(value >> (8 * i));
        }
        public static byte[] Bytes(byte[] bytes, int offset, int count)
        {
            if (bytes == null || offset < 0 || count < 0 || offset > bytes.Length - count)
                throw new ArgumentException("Invalid byte range");
            var value = new byte[count];
            Buffer.BlockCopy(bytes, offset, value, 0, count);
            return value;
        }
        public static void Copy(byte[] source, byte[] target, int offset, int count)
        {
            if (source == null || source.Length != count) throw new ArgumentException("Invalid fixed byte length");
            Buffer.BlockCopy(source, 0, target, offset, count);
        }
    }
